    this._stats.failed++;
    console.error(`[AGENT-FACTORY] ${ctx}: ${msg}`);
    this._emit('system.error', { source: 'agent-factory', context: ctx, message: msg });
    this._emit('system.toast', { msg: `Factory: ${msg}`, type: 'r' });
